const KEY='daily-todo-v1';
let tasks=[],filter='all',storageAvailable=true;
try{const stored=JSON.parse(localStorage.getItem(KEY)||'[]');if(Array.isArray(stored))tasks=stored.filter(t=>t&&typeof t.id==='string'&&typeof t.text==='string'&&typeof t.done==='boolean');}catch{storageAvailable=false;}
const $=s=>document.querySelector(s);
$('#date').textContent=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date());
function save(){try{localStorage.setItem(KEY,JSON.stringify(tasks));storageAvailable=true;}catch{storageAvailable=false;}render();}
function announce(message){$('#announcement').textContent=message;}
function addTask(text){if(typeof text!=='string'||!text.trim()||text.trim().length>200)throw new Error('请输入 1–200 字的任务');const task={id:crypto.randomUUID(),text:text.trim(),done:false};tasks.push(task);filter='all';save();announce('已添加任务');return task;}
function setDone(id,done){const task=tasks.find(t=>t.id===id);if(!task||typeof done!=='boolean')throw new Error('任务或完成状态无效');task.done=done;save();announce(done?'任务已完成':'任务已恢复为待完成');return task;}
function removeTask(id){const i=tasks.findIndex(t=>t.id===id);if(i<0)throw new Error('任务不存在');tasks.splice(i,1);save();announce('已删除任务');}
function render(){const done=tasks.filter(t=>t.done).length;$('#all-count').textContent=tasks.length;$('#active-count').textContent=tasks.length-done;$('#done-count').textContent=done;$('#remaining').textContent=tasks.length-done;$('#clear').disabled=!done;const percent=tasks.length?Math.round(done/tasks.length*100):0;$('#percent').textContent=percent+'%';$('#ring').style.background=`conic-gradient(#2758ec ${percent}%,#e5eaf4 ${percent}%)`;$('#save-status').textContent=storageAvailable?'自动保存到此浏览器':'浏览器存储不可用，关闭后不会保存';document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));const visible=tasks.filter(t=>filter==='all'||(filter==='done'?t.done:!t.done));$('#tasks').replaceChildren();for(const task of visible){const li=document.createElement('li');li.className=task.done?'completed':'';const check=document.createElement('input');check.type='checkbox';check.className='check';check.checked=task.done;check.setAttribute('aria-label',(task.done?'恢复待办：':'完成：')+task.text);check.addEventListener('change',()=>{setDone(task.id,check.checked);const replacement=[...document.querySelectorAll('.check')].find(el=>el.dataset.id===task.id);(replacement||$('#task-input')).focus();});check.dataset.id=task.id;const label=document.createElement('span');label.className='task-text';label.textContent=task.text;const del=document.createElement('button');del.className='delete';del.textContent='×';del.setAttribute('aria-label','删除：'+task.text);del.addEventListener('click',()=>{removeTask(task.id);$('#task-input').focus();});li.append(check,label,del);$('#tasks').append(li);}$('#empty').hidden=visible.length>0;$('#empty-title').textContent=filter==='done'?'完成的事，会在这里相遇':filter==='active'&&tasks.length?'待办清零，做得不错！':'从一件小事开始';$('#empty-description').textContent=filter==='done'?'勾选完成的任务，记录每一点进展。':filter==='active'&&tasks.length?'给自己一点休息，也可以继续添加新的计划。':'添加你的第一项待办，让今天更有方向。';}
$('#add-form').addEventListener('submit',e=>{e.preventDefault();const input=$('#task-input');if(!input.value.trim()){input.setCustomValidity('请输入任务内容');input.reportValidity();return;}addTask(input.value);input.value='';input.focus();});$('#task-input').addEventListener('input',()=>$('#task-input').setCustomValidity(''));document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;render();}));$('#clear').addEventListener('click',()=>{tasks=tasks.filter(t=>!t.done);save();announce('已清除完成的任务');});window.addEventListener('storage',e=>{if(e.key===KEY){try{const data=JSON.parse(e.newValue||'[]');if(Array.isArray(data)&&data.every(t=>t&&typeof t.id==='string'&&typeof t.text==='string'&&typeof t.done==='boolean')){tasks=data;render();}}catch{}}});render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const definitions=[{name:'list_tasks',description:'读取当前浏览器的待办任务',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({tasks:tasks.map(t=>({...t}))})},{name:'add_task',description:'新增一条待办任务并保存到当前浏览器',inputSchema:{type:'object',properties:{text:{type:'string',minLength:1,maxLength:200}},required:['text'],additionalProperties:false},execute:input=>({...addTask(input.text)})},{name:'set_task_completed',description:'更改现有任务的完成状态',inputSchema:{type:'object',properties:{id:{type:'string'},done:{type:'boolean'}},required:['id','done'],additionalProperties:false},execute:input=>({...setDone(input.id,input.done)})},{name:'delete_task',description:'删除指定待办任务',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},execute:input=>{removeTask(input.id);return{deleted:true};}}];for(const tool of definitions){try{Promise.resolve(document.modelContext.registerTool({...tool,annotations:tool.annotations||{readOnlyHint:false,untrustedContentHint:true}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
